#include "../util.h"

// Long enough for "SIGRTMIN+%d" or "SIGRTMAX-%d" or a decimal int.
#define SIGNAL_STR_BUF_LEN (sizeof("SIGRTMIN+") + max_decimal_length(int))

static const char *signal_str(int sig, char buf[static SIGNAL_STR_BUF_LEN])
{
// Generated by scripts/gen_signals.py signal_str.
#ifdef SIGABRT
	if (sig == SIGABRT) return "SIGABRT";
#endif
#ifdef SIGCHLD
	if (sig == SIGCHLD) return "SIGCHLD";
#endif
#ifdef SIGIO
	if (sig == SIGIO) return "SIGIO";
#endif
#ifdef SIGPWR
	if (sig == SIGPWR) return "SIGPWR";
#endif
#ifdef SIGRTMIN
	if (sig == SIGRTMIN) return "SIGRTMIN";
#endif
#ifdef SIGSYS
	if (sig == SIGSYS) return "SIGSYS";
#endif
#ifdef SIGALRM
	if (sig == SIGALRM) return "SIGALRM";
#endif
#ifdef SIGBUS
	if (sig == SIGBUS) return "SIGBUS";
#endif
#ifdef SIGCLD
	if (sig == SIGCLD) return "SIGCLD";
#endif
#ifdef SIGCONT
	if (sig == SIGCONT) return "SIGCONT";
#endif
#ifdef SIGEMT
	if (sig == SIGEMT) return "SIGEMT";
#endif
#ifdef SIGFPE
	if (sig == SIGFPE) return "SIGFPE";
#endif
#ifdef SIGHUP
	if (sig == SIGHUP) return "SIGHUP";
#endif
#ifdef SIGILL
	if (sig == SIGILL) return "SIGILL";
#endif
#ifdef SIGINFO
	if (sig == SIGINFO) return "SIGINFO";
#endif
#ifdef SIGINT
	if (sig == SIGINT) return "SIGINT";
#endif
#ifdef SIGIOT
	if (sig == SIGIOT) return "SIGIOT";
#endif
#ifdef SIGKILL
	if (sig == SIGKILL) return "SIGKILL";
#endif
#ifdef SIGLOST
	if (sig == SIGLOST) return "SIGLOST";
#endif
#ifdef SIGPIPE
	if (sig == SIGPIPE) return "SIGPIPE";
#endif
#ifdef SIGPOLL
	if (sig == SIGPOLL) return "SIGPOLL";
#endif
#ifdef SIGPROF
	if (sig == SIGPROF) return "SIGPROF";
#endif
#ifdef SIGQUIT
	if (sig == SIGQUIT) return "SIGQUIT";
#endif
#ifdef SIGRTMAX
	if (sig == SIGRTMAX) return "SIGRTMAX";
#endif
#ifdef SIGSEGV
	if (sig == SIGSEGV) return "SIGSEGV";
#endif
#ifdef SIGSTKFLT
	if (sig == SIGSTKFLT) return "SIGSTKFLT";
#endif
#ifdef SIGSTOP
	if (sig == SIGSTOP) return "SIGSTOP";
#endif
#ifdef SIGSWI
	if (sig == SIGSWI) return "SIGSWI";
#endif
#ifdef SIGTERM
	if (sig == SIGTERM) return "SIGTERM";
#endif
#ifdef SIGTRAP
	if (sig == SIGTRAP) return "SIGTRAP";
#endif
#ifdef SIGTSTP
	if (sig == SIGTSTP) return "SIGTSTP";
#endif
#ifdef SIGTTIN
	if (sig == SIGTTIN) return "SIGTTIN";
#endif
#ifdef SIGTTOU
	if (sig == SIGTTOU) return "SIGTTOU";
#endif
#ifdef SIGUNUSED
	if (sig == SIGUNUSED) return "SIGUNUSED";
#endif
#ifdef SIGURG
	if (sig == SIGURG) return "SIGURG";
#endif
#ifdef SIGUSR1
	if (sig == SIGUSR1) return "SIGUSR1";
#endif
#ifdef SIGUSR2
	if (sig == SIGUSR2) return "SIGUSR2";
#endif
#ifdef SIGVTALRM
	if (sig == SIGVTALRM) return "SIGVTALRM";
#endif
#ifdef SIGWINCH
	if (sig == SIGWINCH) return "SIGWINCH";
#endif
#ifdef SIGXCPU
	if (sig == SIGXCPU) return "SIGXCPU";
#endif
#ifdef SIGXFSZ
	if (sig == SIGXFSZ) return "SIGXFSZ";
#endif

#if defined(SIGRTMIN) && defined(SIGRTMAX)
if (sig > SIGRTMIN && sig <= (SIGRTMIN + SIGRTMAX) / 2) {
	snprintf(buf, SIGNAL_STR_BUF_LEN, "SIGRTMIN+%d", sig - SIGRTMIN);
	return buf;
}
if (sig > (SIGRTMIN + SIGRTMAX) / 2 && sig < SIGRTMAX) {
	snprintf(buf, SIGNAL_STR_BUF_LEN, "SIGRTMAX-%d", SIGRTMAX - sig);
	return buf;
}
#endif
	snprintf(buf, SIGNAL_STR_BUF_LEN, "%d", sig);
	return buf;
}

#define ProgramExitEvent_traverse NULL

static PyObject *ProgramExitEvent_repr(ProgramExitEvent *self)
{
	int status = drgn_program_exit_event_status(&self->event);
	if (status < 0) {
		char sig_buf[SIGNAL_STR_BUF_LEN];
		return PyUnicode_FromFormat("ProgramExitEvent(-%s)",
					    signal_str(-status, sig_buf));
	}
	return PyUnicode_FromFormat("ProgramExitEvent(%d)", status);
}

static PyObject *ProgramExitEvent_get_status(ProgramExitEvent *self)
{
	return PyLong_FromLong(drgn_program_exit_event_status(&self->event));
}

static PyGetSetDef ProgramExitEvent_getset[] = {
	{"status", (getter)ProgramExitEvent_get_status, NULL,
	 drgn_ProgramExitEvent_status_DOC},
	{},
};

#define ProgramExitEvent_base NULL

static ProgramExitEvent *ProgramExitEvent_new(PyTypeObject *subtype,
					      PyObject *args, PyObject *kwds)
{
	static char *keywords[] = {"status", NULL};
	int status;
	if (!PyArg_ParseTupleAndKeywords(args, kwds, "i:ProgramExitEvent",
					 keywords, &status))
		return NULL;
	struct drgn_program_exit_event *event;
	struct drgn_error *err = drgn_program_exit_event_create(status, &event);
	if (err)
		return set_drgn_error(err);
	return container_of(event, ProgramExitEvent, event);
}

static int ThreadExitEvent_traverse(ThreadExitEvent *self, visitproc visit,
				    void *arg)
{
	Py_VISIT(container_of(self->event.thread_event.thread, Thread, thread));
	return 0;
}

static PyObject *ThreadExitEvent_repr(ThreadExitEvent *self)
{
	Thread *thread = container_of(self->event.thread_event.thread,
				      Thread, thread);
	int status = drgn_thread_exit_event_status(&self->event);
	if (status < 0) {
		char sig_buf[SIGNAL_STR_BUF_LEN];
		return PyUnicode_FromFormat("ThreadExitEvent(%R, -%s)",
					    thread,
					    signal_str(-status, sig_buf));
	}
	return PyUnicode_FromFormat("ThreadExitEvent(%R, %d)", thread, status);
}

static Thread *ThreadExitEvent_get_thread(ThreadExitEvent *self)
{
	Thread *ret = container_of(self->event.thread_event.thread, Thread, thread);
	Py_INCREF(ret);
	return ret;
}

static PyObject *ThreadExitEvent_get_status(ThreadExitEvent *self)
{
	return PyLong_FromLong(drgn_thread_exit_event_status(&self->event));
}

static PyGetSetDef ThreadExitEvent_getset[] = {
	{"thread", (getter)ThreadExitEvent_get_thread, NULL,
	 drgn_ThreadExitEvent_thread_DOC},
	{"status", (getter)ThreadExitEvent_get_status, NULL,
	 drgn_ThreadExitEvent_status_DOC},
	{},
};

#define ThreadExitEvent_base NULL

static ThreadExitEvent *ThreadExitEvent_new(PyTypeObject *subtype,
					    PyObject *args, PyObject *kwds)
{
	static char *keywords[] = {"thread", "status", NULL};
	Thread *thread;
	int status;
	if (!PyArg_ParseTupleAndKeywords(args, kwds, "O!i:ThreadExitEvent",
					 keywords, &Thread_type, &thread,
					 &status))
		return NULL;
	struct drgn_thread_exit_event *event;
	struct drgn_error *err =
		drgn_thread_exit_event_create(&thread->thread, status, &event);
	if (err)
		return set_drgn_error(err);
	return container_of(event, ThreadExitEvent, event);
}

